{id:"f18",ref:"I,21",la:"Leo senex, aper, taurus et asinus",de:"Der alte Löwe, der Eber, der Stier und der Esel",type:"Promythion (V. 1–2)",
moral:"Wer sein früheres Ansehen verliert, wird selbst für Feiglinge zum Gespött.",
v:[
["Quicumque amisit dignitatem pristinam,","Wer auch immer sein früheres Ansehen verloren hat,"],
["ignavis etiam iocus est in casu gravi.","ist im schweren Unglück sogar für Feiglinge ein Spaß."],
["Defectus annis et desertus viribus","Von den Jahren geschwächt und von den Kräften verlassen,"],
["leo cum iaceret spiritum extremum trahens,","lag ein Löwe da und tat den letzten Atemzug;"],
["aper fulmineis spumans venit dentibus,","da kam ein Eber, schäumend, mit blitzenden Hauern,"],
["et vindicavit ictu veterem iniuriam.","und rächte mit einem Stoß ein altes Unrecht."],
["Infestis taurus mox confodit cornibus","Bald darauf durchbohrte ein Stier mit feindlichen Hörnern"],
["hostile corpus. Asinus, ut vidit ferum","den verhassten Leib. Als der Esel sah, dass man das Raubtier"],
["impune laedi, calcibus frontem extudit.","ungestraft verletzen konnte, schlug er ihm mit den Hufen die Stirn ein."],
["At ille exspirans Fortis indigne tuli","Doch jener sagte im Sterben: „Dass Tapfere mich verhöhnen,"],
["mihi insultare: te, Naturae dedecus,","habe ich nur mit Unwillen ertragen; dich aber, du Schandfleck der Natur,"],
["quod ferre certe cogor bis videor mori.","ertragen zu müssen – dabei ist mir, als stürbe ich zweimal.“"]],
aufbau:[["Promythion","1–2","Die Lehre steht voran: Wer sein Ansehen verliert, wird selbst von Feiglingen verhöhnt."],["Situation","3–4","Der Löwe liegt altersschwach im Sterben."],["Actio 1–3","5–9","Drei Angreifer nacheinander: Eber, Stier, Esel – die Reihe wird immer unwürdiger."],["Ergebnis","10–12","Der sterbende Löwe wertet: Die Tapferen zu ertragen war schwer, den Esel ist doppelter Tod."]],
stil:[["Klimax (absteigend)","aper – taurus – asinus (V. 5–9)","Zuerst zwei starke Gegner mit echtem Grund, dann der feige Esel: Die Demütigung steigert sich, indem der Gegner immer geringer wird."],["Metaphorische Beiwörter","fulmineis … dentibus (V. 5)","„blitzende Hauer“ – der Eber greift wie ein Naturgewalt an."],["Invektive","Naturae dedecus (V. 11)","Die schärfste Beschimpfung der Fabel, gerichtet nicht gegen die Tat, sondern gegen das Wesen des Esels."],["Hyperbel im Schlussvers","bis videor mori (V. 12)","Der doppelte Tod: Die Schmach wiegt schwerer als das Sterben selbst."]],
fragen:[["Warum ist die Reihenfolge der drei Angreifer entscheidend?","Eber und Stier sind starke Tiere und rächen ein altes Unrecht (veterem iniuriam) – das ist im Rahmen der Fabellogik noch nachvollziehbar. Der Esel dagegen tritt zu, nur weil es gefahrlos ist (impune). Die absteigende Reihe macht die letzte Demütigung zur eigentlichen Pointe."],["Erkläre den Ausdruck bis videor mori.","Der Löwe stirbt körperlich – und zugleich stirbt seine Würde, weil ihn ein verachtetes Tier schlägt. Die Hyperbel sagt: Ehrverlust wiegt für ihn so schwer wie der Tod selbst. Das entspricht dem römischen Wert der dignitas."],["Wie verhält sich diese Fabel zu Vacca et capella, ovis et leo?","Dort ist der Löwe der rücksichtslos Mächtige, hier das Opfer. Zusammen zeigen beide Fabeln den vollen Kreislauf der Macht: Wer oben ist, nimmt sich alles; wer stürzt, wird von allen getreten. Phaedrus zeichnet kein Bild treuer Gefolgschaft, sondern reiner Machtverhältnisse."]],
voc:[["quicumque","quīcumque","quaecumque, quodcumque","wer auch immer"],["amisit","āmittere","āmittō, āmīsī, āmissum","verlieren"],["dignitatem","dīgnitās","ātis f","das Ansehen, die Würde"],["pristinam","prīstinus","a, um","früher, ehemalig"],["ignavis","īgnāvus","a, um","feige, träge"],["iocus","iocus","ī m","der Scherz, der Spaß"],["casu","cāsus","ūs m","der Fall, das Unglück"],["defectus","dēficere","dēficiō, dēfēcī, dēfectum","schwächen, im Stich lassen"],["annis","annus","ī m","das Jahr"],["desertus","dēserere","dēserō, dēseruī, dēsertum","verlassen, im Stich lassen"],["viribus","vīs","Pl. vīrēs, vīrium f","die Kräfte"],["iaceret","iacēre","iaceō, iacuī","liegen"],["spiritum","spīritus","ūs m","der Atem, der Hauch"],["extremum","extrēmus","a, um","der äußerste, der letzte"],["trahens","trahere","trahō, trāxī, tractum","ziehen"],["aper","aper","aprī m","der Eber"],["fulmineis","fulmineus","a, um","blitzend, blitzartig"],["spumans","spūmāre","spūmō","schäumen"],["dentibus","dēns","dentis m","der Zahn, der Hauer"],["vindicavit","vindicāre","vindicō","rächen; beanspruchen"],["ictu","ictus","ūs m","der Stoß, der Schlag"],["veterem","vetus","Gen. veteris","alt"],["iniuriam","iniūria","ae f","das Unrecht"],["infestis","īnfēstus","a, um","feindlich, bedrohlich"],["taurus","taurus","ī m","der Stier"],["confodit","cōnfodere","cōnfodiō, cōnfōdī, cōnfossum","durchbohren"],["cornibus","cornū","ūs n","das Horn"],["hostile","hostīlis","e","feindlich"],["corpus","corpus","corporis n","der Körper, der Leib"],["asinus","asinus","ī m","der Esel"],["ferum","ferus","ī m","das wilde Tier"],["impune","impūne","Adv.","ungestraft"],["laedi","laedere","laedō, laesī, laesum","verletzen"],["calcibus","calx","calcis f","die Ferse, der Huf"],["frontem","frōns","frontis f","die Stirn"],["extudit","extundere","extundō, extūdī","herausschlagen, einschlagen"],["exspirans","exspīrāre","exspīrō","aushauchen, sterben"],["fortis","fortis","e","tapfer"],["indigne","indīgnē","Adv.","unwillig, empört"],["insultare","īnsultāre","īnsultō (m. Dat.)","verhöhnen, verspotten"],["dedecus","dēdecus","dēdecoris n","die Schande, der Schandfleck"],["cogor","cōgere","cōgō, coēgī, coāctum","zwingen"],["bis","bis","","zweimal"],["mori","morī","morior, mortuus sum","sterben"]]}

