const PROLOG={la:"Prologus (Buch I)",v:[
["Aesopus auctor quam materiam repperit,","Den Stoff, den Äsop als Urheber gefunden hat,"],
["hanc ego polivi versibus senariis.","habe ich in Senaren (sechsfüßigen Versen) ausgefeilt."],
["Duplex libelli dos est: quod risum movet,","Doppelt ist die Gabe des Büchleins: dass es zum Lachen bringt"],
["et quod prudenti vitam consilio monet.","und dass es mit klugem Rat das Leben lenkt."],
["Calumniari si quis autem voluerit,","Wenn aber jemand kritteln will,"],
["quod arbores loquantur, non tantum ferae,","weil Bäume sprechen, nicht nur wilde Tiere,"],
["fictis iocari nos meminerit fabulis.","soll er daran denken, dass wir mit erfundenen Fabeln scherzen."]]};

